select kind,slug,title,summary,body,status,published_at,sort_order,featured,metadata from jsonb_to_recordset('[{"kind":"projects","slug":"ecommerce-lms","title":"이커머스·LMS","summary":"Java·Spring·데이터베이스 기반 웹 팀 프로젝트.","body":"## 맡은 일\n- 사용자·상품·고객센터 도메인 기능 구현\n- 중복 로직과 API 구조 정리\n\n## 배포 문제\nCORS 문제를 만나 요청이 오가는 환경과 보안 설정을 함께 점검했습니다.\n\n국비 웹 개발 교육의 팀 프로젝트입니다.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":5,"featured":false,"metadata":{"category":"웹 백엔드","role":"사용자 · 상품 · 고객센터 도메인 구현","listRole":"Java · Spring","period":"2024.08–11","links":[{"label":"이커머스 코드","url":"https://github.com/Juno31323/TotalPlatform_Ecommerce2"},{"label":"LMS 코드","url":"https://github.com/Juno31323/TotalPlatform_LMS3"}]}},{"kind":"projects","slug":"firezone","title":"Firezone","summary":"공공데이터로 소방전용구역을 안내하는 앱.","body":"## 구현\n- React Native·Expo 앱\n- NestJS CRUD API\n- 공공데이터 기반 소방전용구역 정보 조회\n\n## 배포\nDocker로 서버 환경을 구성하고, GitHub와 Google Cloud Run을 연결해 자동 배포를 구성했습니다.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":1,"featured":true,"metadata":{"category":"앱 · 백엔드","role":"개인 개발 · 배포","listRole":"React Native · NestJS","period":"2025.03","status":"개발·배포","links":[{"label":"앱 코드","url":"https://github.com/Juno31323/firezone-expo-view"},{"label":"API 코드","url":"https://github.com/Juno31323/firezone-nest-api"}],"cardImage":"/images/portfolio/firezone-art.webp","cardAlt":"소방구역을 표현한 지도와 소방차 일러스트"}},{"kind":"projects","slug":"printsafe","title":"PrintSafe","summary":"첫 문서 누락과 스풀링 중단을 다룬 PDF 일괄 인쇄 도구.","body":"## 인쇄가 멈추는 문제\n학원 조교로 여러 PDF를 인쇄할 때 첫 문서가 누락되거나 스풀링 공간 부족으로 작업이 멈췄습니다.\n\n## 구현과 개선\n- PDF 일괄 인쇄 도구 개발\n- 사용 중 발생한 지연·누락 개선\n- 스풀러 복구 흐름 개선","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":2,"featured":true,"metadata":{"category":"업무 도구","role":"도구 개발 · 사용 중 개선","cardImage":"/images/portfolio/printsafe-art.webp","cardAlt":"여러 PDF 문서를 겹쳐 놓은 일러스트"}},{"kind":"projects","slug":"runningapp-lift","title":"RunningAppLIFT","summary":"러닝 커뮤니티·운동 기록·코스와 경로를 다루는 팀 프로젝트.","body":"## 맡은 일\n- 백엔드 도메인 API 전반 구현\n- Firebase를 활용한 찜하기·채팅 기능 구현\n\n개발 부트캠프 팀 프로젝트입니다.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":4,"featured":false,"metadata":{"category":"러닝 앱 · GIS","role":"백엔드 도메인 API · 찜하기 · 채팅","period":"2025.03–04"}},{"kind":"projects","slug":"shared-auth-api","title":"공통 인증 API","summary":"팀의 세 프로젝트에서 사용할 로그인·회원가입 API.","body":"## 구현\n- JWT 기반 인증 API\n- 로그인·회원가입\n- 공통 인증 처리를 위한 커스텀 어노테이션과 예외\n\n국비 웹 개발 교육에서 팀 프로젝트의 공통 인증 기능을 맡았습니다.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":6,"featured":false,"metadata":{"category":"인증 · 백엔드","role":"개인 구현","listRole":"JWT","period":"2024.08–11"}},{"kind":"research","slug":"university-notice-rag","title":"Chat2B-AU","summary":"대학 공지 RAG 챗봇과 OCR·레이아웃 구조화에 따른 검색 성능 연구.","body":"## 대학 공지 질의응답\n입학 정보를 찾을 때 기존 FAQ나 챗봇에서 구체적인 답을 얻기 어려워, 대학 공지를 근거로 답하는 시스템을 만들었습니다. 2026년 4월부터 준비했고, 주요 개발·실험은 5~8월에 진행했습니다.\n\n## 구현\n- Spring Boot 질의응답 API\n- PostgreSQL·pgvector 기반 저장·벡터 검색\n- BM25 키워드 검색과 벡터 검색 결합\n- 검색 근거가 부족할 때 답변 제한\n- 첨부 문서 OCR·레이아웃 처리·색인 구성\n- Python 조건별 실험·검색 및 답변 결과 평가\n\nJava, Spring Boot, PostgreSQL, Supabase, pgvector, Python, OpenAI API, Gemini Embedding API를 사용했습니다.\n\n## 논문\n**시각적 문서 기반 RAG에서 OCR 및 레이아웃 구조화에 따른 검색 성능 분석**\n\n민준호 제1저자 · 정민영 교신저자\n\nOCR로 검색 가능한 정보를 늘리는 효과와, 같은 정보를 레이아웃에 따라 배열하는 효과를 분리해 비교했습니다.\n\n## 데이터\n| 항목 | 구성 |\n| --- | --- |\n| 기준 데이터 | 2026년 5월 텍스트 공지 55건 · 390청크 |\n| OCR 처리 | CLOVA OCR V2로 공지–첨부 연결 192건 중 164건 처리 |\n| 확보한 OCR 정보 | 고유 공지 100건 |\n| OCR 추가 조건 | 공지 155건 |\n| 평가 문항 | 49개 |\n\n## 비교 조건\n| 조건 | 구성 |\n| --- | --- |\n| C1 | 텍스트 전용 |\n| C2 | OCR 원본 순서 |\n| C3 | 경계 상자 기반 그룹화·청크 재구성 |\n| C4P | 같은 OCR 필드·청크 배정, 원본 순서 |\n| C4L | 같은 OCR 필드·청크 배정, 행 단위 정렬 |\n\nBM25와 Gemini 임베딩 검색을 RRF로 결합했습니다. Recall@k·MRR@5·nDCG@5를 비교하고 McNemar 검정, Holm 보정, 대응표본 부트스트랩을 적용했습니다.\n\n## 결과\n| 검색 지표 | 텍스트 전용 | OCR 추가 |\n| --- | --- | --- |\n| 정답 공지가 색인에 포함된 문항 | 33/49 | 46/49 |\n| Recall@5 | 67.35% | 89.80% |\n\nRecall@5의 Holm 보정 p값은 0.0088입니다. 위 수치는 **검색 지표**이며 답변 정확도를 뜻하지 않습니다.\n\n같은 OCR 필드·청크 배정으로 비교한 C4P·C4L에서는, 시험한 규칙 기반 레이아웃 표현의 추가 검색 이점을 확인하지 못했습니다.\n\n## 발표·원고\n- KICS 추계학술발표회 채택 통보 · 포스터 제작\n- J-KICS 확장 원고 준비","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":3,"featured":true,"metadata":{"category":"RAG · 정보검색","role":"백엔드 · 검색 · OCR 처리 · 실험 평가","listRole":"Spring Boot · pgvector · Python","period":"2026.05–08","status":"KICS 추계학술발표회 채택 통보 · 포스터 제작","links":[{"label":"GitHub","url":"https://github.com/Juno31323/Chat2B-AU"}],"cardImage":"/images/portfolio/rag-art.webp","cardAlt":"대학 공지 질의응답을 표현한 두 말풍선 일러스트"}},{"kind":"timeline","slug":"academy-assistant","title":"학원 조교","summary":"","body":"숙제 채점·인쇄·문서 편집. 인쇄 중단 문제를 계기로 PrintSafe 개발.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":3,"featured":false,"metadata":{"period":"2026","category":"업무"}},{"kind":"timeline","slug":"ansan-university","title":"안산대학교 인공지능소프트웨어학과","summary":"","body":"재학 중. Python, 서버·리눅스, 웹, 생성형 AI, 자료구조, AI 자동화 수업·실습.\n\n- 2026년 학과 학생회 참여","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":2,"featured":false,"metadata":{"period":"2026.03–","category":"대학"}},{"kind":"timeline","slug":"certificate-written","title":"정보처리기능사 필기 합격","summary":"","body":"실기 준비 중.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":1,"featured":false,"metadata":{"period":"2026.09","category":"자격시험"}},{"kind":"timeline","slug":"data-cleaning","title":"AI 데이터 정제 활동","summary":"","body":"엘비에스테크에서 진행한 AI 데이터 정제 활동에 참여했습니다.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":5,"featured":false,"metadata":{"period":"2025.09.10–11.10","category":"데이터"}},{"kind":"timeline","slug":"development-bootcamp","title":"개발 부트캠프","summary":"","body":"React Native·NestJS·Docker 학습. RunningAppLIFT 팀 프로젝트와 개인 앱 개발·배포.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":6,"featured":false,"metadata":{"period":"2025.02.25–04.25","category":"교육"}},{"kind":"timeline","slug":"qualification-exam","title":"고등학교 졸업학력 검정고시 합격","summary":"","body":"","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":8,"featured":false,"metadata":{"period":"2024.05","category":"학력"}},{"kind":"timeline","slug":"web-training","title":"국비 웹 개발 교육","summary":"","body":"Java·Spring·데이터베이스·웹 개발. 이커머스·LMS 팀 프로젝트와 공통 인증 API 구현.","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":7,"featured":false,"metadata":{"period":"2024.06.18–11.12","category":"교육"}},{"kind":"pages","slug":"about","title":"저에 대해","summary":"민준호의 소개와 학습 기록.","body":"<h2>대학에 오기 전</h2>\n      <p>검정고시 이후 2024년 국비 웹 개발 교육에서 Java·Spring을 배웠습니다. 이커머스·LMS 팀 프로젝트와 공통 인증 API를 구현했습니다.</p>\n      <p>2025년 부트캠프에서는 React Native·NestJS·Docker를 배웠습니다. RunningAppLIFT의 백엔드를 맡고, 개인 앱 Firezone을 개발·배포했습니다.</p>\n      <p>2025년 9~11월에는 엘비에스테크에서 AI 데이터 정제 활동에 참여했습니다.</p>\n      <h2>대학에서</h2>\n      <p>대학 공지를 검색하는 Chat2B-AU를 만들고, OCR과 문서 레이아웃이 검색 성능에 미치는 영향을 비교했습니다.</p>\n      <p>학원 조교로 인쇄 업무를 하며 겪은 문제는 PDF 일괄 인쇄 도구 PrintSafe로 다뤘습니다.</p>\n      <h2>수업·실습</h2>\n      <table><thead><tr><th>분야</th><th>내용</th></tr></thead><tbody>\n        <tr><td>Python·자료구조</td><td>리스트·스택·큐·덱. Tkinter A* 격자 시각화와 백트래킹 퀸 배치.</td></tr>\n        <tr><td>A* 실습</td><td>맨해튼 거리, 우선순위 큐, 장애물·방문 노드·최종 경로 표시.</td></tr>\n        <tr><td>웹</td><td>HTML·CSS·JavaScript·DOM. 뉴스 페이지 레이아웃 재현·발표, 여행지 데이터를 객체 배열로 구성·콘솔 출력.</td></tr>\n        <tr><td>리눅스·서버</td><td>Rocky Linux의 디스크 쿼터·파일 권한·테스트 파일 생성. 커널 모듈·의존성, LVM·RAID, NAT·포트 포워딩, 부팅·디스크 구성.</td></tr>\n        <tr><td>AI·자동화</td><td>생성형 AI·인공지능개론·AI 자동화 프로세스. 파일 입력 → 메시지 생성·검토 → GUI 조작.</td></tr>\n      </tbody></table>\n      <h2>사용한 기술</h2>\n      <table><tbody>\n        <tr><th>백엔드·인증</th><td>Java · Spring Boot · NestJS · REST API · JWT</td></tr>\n        <tr><th>데이터·검색</th><td>PostgreSQL · Supabase · pgvector · Firebase · BM25 · 벡터 검색 · RRF · 공공데이터 · GIS</td></tr>\n        <tr><th>AI·실험</th><td>Python · CLOVA OCR V2 · OpenAI API · Gemini Embedding API · RAG 평가</td></tr>\n        <tr><th>앱·웹</th><td>React Native · Expo · HTML · CSS · JavaScript · DOM · Tkinter</td></tr>\n        <tr><th>배포·시스템</th><td>Docker · Google Cloud Run · GitHub 자동 배포 · GitHub Pages · Rocky Linux</td></tr>\n      </tbody></table>\n      <h2>관심과 학습 계획</h2>\n      <ul><li>AI 시스템 · RAG·정보검색 · MLOps</li><li>SQLD · C·C++·Rust</li><li>ADsP 시험 준비</li><li>OpenClaw·OpenManus 등 멀티 에이전트 도구 탐색</li></ul>","status":"published","published_at":"2026-11-09T00:00:00Z","sort_order":0,"featured":false,"metadata":{}}]'::jsonb) as x(kind text,slug text,title text,summary text,body text,status text,published_at timestamptz,sort_order integer,featured boolean,metadata jsonb) on conflict (kind,slug) do nothing;
insert into public.site_settings(id,data) values ('profile','{"name":"민준호","school":"안산대학교","major":"인공지능소프트웨어학과","intro":"백엔드와 앱을 만들고, 대학 공지 RAG를 연구합니다.","github":"https://github.com/Juno31323","heroPhoto":"/images/portfolio/portrait.webp","photo":"/images/min-junho.jpg","photoAlt":"안경과 짙은색 티셔츠를 착용한 민준호의 프로필 사진","researchSummary":"49개 문항으로 OCR과 레이아웃에 따른 검색 성능을 비교했습니다.","interests":"### RAG·정보검색\nOCR · 하이브리드 검색 · 검색 평가\n\n### AI 시스템·MLOps\n운영·배포\n\n### 다음 공부\nSQLD · C · C++ · Rust"}'::jsonb) on conflict (id) do nothing;
